import{_ as t,c as s,o as l,ag as n}from"./chunks/framework.BtwP-r-R.js";const c=JSON.parse('{"title":"La pensée computationnelle","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"resolution_problemes.md","filePath":"resolution_problemes.md"}'),i={name:"resolution_problemes.md"};function a(r,e,o,u,d,p){return l(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="la-pensee-computationnelle" tabindex="-1">La pensée computationnelle <a class="header-anchor" href="#la-pensee-computationnelle" aria-label="Permalink to &quot;La pensée computationnelle&quot;">​</a></h1><p>Mais qu&#39;est-ce que la pensée computationnelle exactement? Jetons un coup d&#39;œil à une définition technique ...</p><p><i>&quot;La pensée computationnelle est le processus de pensée impliqué dans la formulation des problèmes et de leurs solutions afin que les solutions soient représentées sous une forme qui peut être efficacement réalisée par un système de traitement de l&#39;information (un ordinateur). &quot; </i></p><p>La pensée computationnelle pourrait être décrite tout simplement comme « <strong>penser comme un informaticien</strong> ».</p><h2 id="les-4-composantes-de-la-pensee-computationnelle" tabindex="-1">Les 4 composantes de la pensée computationnelle <a class="header-anchor" href="#les-4-composantes-de-la-pensee-computationnelle" aria-label="Permalink to &quot;Les 4 composantes de la pensée computationnelle&quot;">​</a></h2><h3 id="la-decomposition" tabindex="-1">La décomposition <a class="header-anchor" href="#la-decomposition" aria-label="Permalink to &quot;La décomposition&quot;">​</a></h3><p>Avant que les ordinateurs ne puissent résoudre un problème, le problème et les moyens de le résoudre doivent être compris. La décomposition aide en décomposant les problèmes complexes en petites parties plus faciles à gérer.</p><p><strong>Qu&#39;est-ce que la décomposition?</strong></p><p>La décomposition implique de décomposer un problème ou un système complexe en parties plus petites qui sont plus faciles à gérer et à comprendre. Les plus petites pièces peuvent ensuite être examinées et résolues, ou conçues individuellement, car elles sont plus simples à utiliser.</p><p><strong>Pourquoi la décomposition est-elle importante?</strong></p><p>Si un problème n&#39;est pas décomposé, il est beaucoup plus difficile à résoudre. Il est beaucoup plus difficile de traiter simultanément de nombreuses étapes différentes que de décomposer un problème en plusieurs petits problèmes et de résoudre chacun d&#39;entre eux, un à la fois. Décomposer le problème en parties plus petites signifie que chaque problème plus petit peut être examiné plus en détail. De même, il est plus facile d&#39;essayer de comprendre le fonctionnement d&#39;un système complexe en utilisant la décomposition. Par exemple, comprendre comment fonctionne un ordinateur est plus simple si l’ordinateur entier est séparé en parties plus petites et que chaque partie est examinée pour voir comment cela fonctionne plus en détail.</p><p><strong>La décomposition en pratique</strong></p><p>Nous effectuons de nombreuses tâches au quotidien sans même y penser - ou les décomposer - comme le brossage des dents.</p><p><strong>Exemple 1: Se brosser les dents</strong></p><p>Pour décomposer le problème de la façon de se brosser les dents, il faudrait considérer:</p><ul><li>quelle brosse à dents utiliser</li><li>combien de temps brosser</li><li>avec quelle force appuyer la brosse sur nos dents</li><li>quel dentifrice utiliser</li></ul><p><strong>Exemple 2: Résoudre un crime</strong></p><p>Ce n&#39;est normalement que lorsqu&#39;on nous demande de faire une tâche nouvelle ou plus complexe que nous commençons à y réfléchir en détail - à décomposer la tâche.</p><p>Imaginez qu&#39;un crime a été commis. Résoudre un crime peut être un problème très complexe, car il y a beaucoup de choses à considérer. Par exemple, un policier aurait besoin de connaître la réponse à une série de problèmes mineurs:</p><ul><li>quel crime a été commis</li><li>quand le crime a été commis</li><li>où le crime a été commis</li><li>quelles preuves il y a</li><li>s&#39;il y avait des témoins</li><li>s&#39;il y a eu récemment des crimes similaires</li></ul><p>Le problème complexe du crime commis a maintenant été décomposé en problèmes plus simples qui peuvent être examinés individuellement, en détail.</p><h3 id="la-reconnaissance-des-entites-modeles" tabindex="-1">La reconnaissance des entités (modèles) <a class="header-anchor" href="#la-reconnaissance-des-entites-modeles" aria-label="Permalink to &quot;La reconnaissance des entités (modèles)&quot;">​</a></h3><p>Une fois que nous avons décomposé un problème complexe, cela aide à examiner les petits problèmes à la recherche de similitudes ou de « modèles ». Une entité est un concept abstrait qui représente une chose ou un concept du monde réel. Dans la modélisation de données ou dans la conception logicielle, une entité peut être représentée par un ensemble de caractéristiques.</p><p>Imaginez que nous voulons dessiner une série de chats.</p><p>Tous les chats partagent des caractéristiques communes. Entre autres, ils ont tous des yeux, une queue et de la fourrure. Ils aiment aussi manger du poisson et émettre des miaulements.</p><p>Parce que nous savons que tous les chats ont des yeux, une queue et une fourrure, nous pouvons faire une bonne tentative pour dessiner un chat, simplement en incluant ces caractéristiques communes.</p><p>Une fois que nous savons comment décrire un chat, nous pouvons en décrire d&#39;autres, simplement en suivant ce schéma. Les seules choses qui diffèrent sont les spécificités:</p><ul><li>un chat peut avoir les yeux verts , une longue queue et une fourrure noire</li><li>un autre chat peut avoir les yeux jaunes , une queue courte et une fourrure rayée.</li></ul><p>Maintenant si nous voulons dessiner un chat, il est simple de le faire. Nous savons que tous les chats suivent ce modèle, nous n&#39;avons donc pas à nous arrêter chaque fois que nous commençons à dessiner un nouveau chat pour résoudre ce problème. À partir de l&#39;entité chat que nous avont défini, nous pouvons rapidement dessiner plusieurs chats.</p><p><strong>Trouver les entités</strong></p><p>Pour trouver les entités à l&#39;intérieur d&#39;un problème, il s&#39;agit de <strong>trouver les éléments identiques ou très similaires</strong>.</p><p>Par exemple, la tâche de préparer un gâteau peut être décomposée en différents petits problèmes (étapes) :</p><ul><li>Quel est le genre de gâteau?</li><li>Quels sont les ingrédients et la quantité de chacun?</li><li>Pour combien de personnes?</li><li>Quel est le temps de cuisson?</li><li>Quand est-ce ajouter chaque ingrédient?</li><li>Etc.</li></ul><p>Une fois que nous savons comment faire un type de gâteau, il est simple de voir que préparer d&#39;autre type de gâteau n&#39;est pas si différent.</p><ul><li>Chaque gâteau aura besoin d&#39;un certain nombre d&#39;ingrédients</li><li>Les ingrédients seront ajoutés à un moment précis</li><li>Chaque gâteau aura un temps de cuisson</li><li>Etc.</li></ul><p>Une fois les entités identifiés, il est possible de trouver des solutions communes entre les problèmes :</p><ul><li>Préchauffer le four à la température X.</li><li>Mélanger une quantité X d&#39;un ingrédient Y.</li><li>Cuire pendant X temps.</li></ul><h3 id="l-abstraction" tabindex="-1">L&#39;abstraction <a class="header-anchor" href="#l-abstraction" aria-label="Permalink to &quot;L&#39;abstraction&quot;">​</a></h3><p>Une fois que nous avons identifié des entités dans nos problèmes, nous utilisons l&#39;abstraction pour rassembler les caractéristiques générales et pour filtrer les détails dont nous n&#39;avons pas besoin pour résoudre notre problème.</p><p>L&#39;abstraction est le processus de filtrage - ignorant - les caractéristiques des entités dont nous n&#39;avons pas besoin.</p><p>Précédemment, nous avons identifié les modèles nous permettant de dessiner des chats. Nous avons noté que tous les chats ont des caractéristiques générales, communes à tous les chats, par exemple des yeux, une queue, une fourrure, un goût pour les poissons et la capacité de miauler.</p><p>De plus, chaque chat a des caractéristiques spécifiques comme une fourrure noire, une longue queue, des yeux verts, un amour du saumon et un miaulement fort. Celles-ci sont en fait des détails.</p><p>Pour dessiner un chat de base, nous devons savoir qu&#39;il a une queue, de la fourrure et des yeux. Ces caractéristiques sont pertinentes. Cependant, nous n&#39;avons pas besoin de connaître le son qu&#39;il fait ou s&#39;il aime le poisson. Ces caractéristiques ne sont pas pertinentes et peuvent être filtrées.</p><p>L&#39;abstraction nous permet de créer une idée générale de ce qu&#39;est le problème et comment le résoudre. Le processus nous demande de supprimer tous les détails spécifiques de toutes les entités qui ne nous aideront pas à résoudre notre problème.</p><p><strong>En pratique</strong></p><p>Lors de la cuisson d&#39;un gâteau, il existe certaines caractéristiques générales entre les gâteaux. Par exemple:</p><ul><li>Un gâteau a besoin d&#39;ingrédients</li><li>Chaque ingrédient a besoin d&#39;une quantité spécifiée</li><li>Un gâteau a besoin d&#39;un temps de cuisson</li></ul><p>Lors de l&#39;abstraction, nous supprimons des détails spécifiques et conservons caractéristiques générales pertinentes.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Caractéristiques générales</th><th style="text-align:left;">détails spécifique</th></tr></thead><tbody><tr><td style="text-align:left;">Nous devons savoir qu&#39;un gâteau a des ingrédients.</td><td style="text-align:left;">Nous n&#39;avons pas besoin de savoir quels sont ces ingrédients</td></tr><tr><td style="text-align:left;">Nous devons savoir que chaque ingrédient a une quantité spécifiée</td><td style="text-align:left;">Nous n&#39;avons pas besoin de savoir quelle est cette quantité</td></tr><tr><td style="text-align:left;">Nous devons savoir que chaque gâteau a besoin d&#39;un temps de cuisson</td><td style="text-align:left;">Nous n&#39;avons pas besoin de savoir combien de temps il faut</td></tr></tbody></table><p>Une fois l&#39;entité identifié et ses caractéristique générales, nous pouvons identifier les comportements. Par exemple, dans l&#39;exemple du chat :</p><table tabindex="0"><thead><tr><th style="text-align:left;">Caractéristiques générales</th><th style="text-align:left;">détails spécifique</th></tr></thead><tbody><tr><td style="text-align:left;">Un chat peu manger</td><td style="text-align:left;">Nous n&#39;avons pas besoin de savoir qu&#39;est-ce qu&#39;il mange</td></tr><tr><td style="text-align:left;">Un chat peu miauler</td><td style="text-align:left;">Nous n&#39;avons pas besoin de savoir le type de miaulement (fort ou faible)</td></tr></tbody></table><h3 id="l-algorithme-et-le-code" tabindex="-1">l&#39;algorithme et le code <a class="header-anchor" href="#l-algorithme-et-le-code" aria-label="Permalink to &quot;l&#39;algorithme et le code&quot;">​</a></h3><p>Une fois l&#39;entité identifié, ses caractéristique générales et ses comportements, il ne nous reste qu&#39;à écrire l&#39;algorithme et le code pour résoudre le problème.</p><h2 id="exemple-de-decomposition-de-probleme" tabindex="-1">Exemple de décomposition de problème <a class="header-anchor" href="#exemple-de-decomposition-de-probleme" aria-label="Permalink to &quot;Exemple de décomposition de problème&quot;">​</a></h2><h3 id="probleme" tabindex="-1">Problème <a class="header-anchor" href="#probleme" aria-label="Permalink to &quot;Problème&quot;">​</a></h3><p>La rémunération hebdomadaire d&#39;un employé dépend du taux de rémunération et du nombre d&#39;heures travaillées par semaine. Les employés travaillent au moins une heure par semaine et au maximum 60. Un employé qui travaille plus de 40 heures est payé 1,5 fois son taux de rémunération pour toutes les heures travaillées au-delà de 40. Le salaire minimum est de 15$ par heure. Un programme est nécessaire pour calculer et produire la paie hebdomadaire de tout employé.</p><details class="details custom-block"><summary><strong>1) Décomposer le problème global en plusieurs problèmes plus petits et plus faciles à résoudre.</strong></summary><ul><li>Connaître le nombre d&#39;heures travaillées</li><li>Connaître combien de ces heures doivent être payées au taux normal</li><li>Connaître combien de ces heures, le cas échéant, doivent être payées au taux des heures supplémentaires</li><li>Calculer le salaire pour les heures normales</li><li>Calculer le salaire des heures supplémentaires</li><li>Additionner la rémunération des heures normales et supplémentaires</li><li>Afficher le résultat</li></ul></details><details class="details custom-block"><summary><strong>2) Identifier les entités ainsi que leur caractéristiques et comportements</strong></summary><ul><li>Employe : <ul><li>Caractéristiques : <ul><li>Nom</li><li>Prénom</li><li>Taux horaire</li><li>Nombre d&#39;heures travaillées</li></ul></li><li>Comportement : <ul><li>Aucun</li></ul></li></ul></li></ul></details><details class="details custom-block"><summary><strong>3) Identifier les variables en entrée et en sortie et les constantes qui seront nécesssaires</strong></summary><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Type de données</th><th style="text-align:left;">Entrée/Sortie</th></tr></thead><tbody><tr><td style="text-align:left;">noEmploye</td><td style="text-align:left;">ushort</td><td style="text-align:left;">Entrée</td></tr><tr><td style="text-align:left;">nom</td><td style="text-align:left;">string</td><td style="text-align:left;">Entrée</td></tr><tr><td style="text-align:left;">prenom</td><td style="text-align:left;">string</td><td style="text-align:left;">Entrée</td></tr><tr><td style="text-align:left;">tauxHoraire</td><td style="text-align:left;">decimal</td><td style="text-align:left;">Entrée</td></tr><tr><td style="text-align:left;">vectEmployes</td><td style="text-align:left;">Employe[]</td><td style="text-align:left;">Entrée</td></tr><tr><td style="text-align:left;">nbHeuresNormales</td><td style="text-align:left;">byte</td><td style="text-align:left;">Entrée</td></tr><tr><td style="text-align:left;">nbHeuresSupp</td><td style="text-align:left;">byte</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">montantHeuresNormales</td><td style="text-align:left;">decimal</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">montantHeuresSupp</td><td style="text-align:left;">decimal</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">montantTotal</td><td style="text-align:left;">decimal</td><td style="text-align:left;">Sortie</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Constantes</th><th style="text-align:left;">Type de données</th></tr></thead><tbody><tr><td style="text-align:left;">TAUX_HORAIRE_SUPPLEMENTAIRE</td><td style="text-align:left;">float</td></tr><tr><td style="text-align:left;">NB_HEURES_MAX</td><td style="text-align:left;">byte</td></tr><tr><td style="text-align:left;">NB_HEURES_MIN</td><td style="text-align:left;">byte</td></tr><tr><td style="text-align:left;">NB_HEURES_NORMAL</td><td style="text-align:left;">byte</td></tr></tbody></table><p>::</p><details class="details custom-block"><summary><strong>4) Idenifier les fonctions ainsi que leurs entréeet sortie.</strong></summary><table tabindex="0"><thead><tr><th style="text-align:left;">Fonctions</th><th style="text-align:left;">Entrée(s)</th><th style="text-align:left;">Sortie</th></tr></thead><tbody><tr><td style="text-align:left;">CalculerNbHeuresNormale</td><td style="text-align:left;">nbHeuresTravaillees</td><td style="text-align:left;">nbHeuresNormales</td></tr><tr><td style="text-align:left;">CalculerNbHeuresSupp</td><td style="text-align:left;">nbHeuresTravaillees</td><td style="text-align:left;">nbHeuresSupp</td></tr><tr><td style="text-align:left;">CalculerPayeNormale</td><td style="text-align:left;">nbHeuresNormales</td><td style="text-align:left;">montantHeuresNormales</td></tr><tr><td style="text-align:left;">CalculerPayeSupp</td><td style="text-align:left;">nbHeuresSupp</td><td style="text-align:left;">montantHeuresSupp</td></tr><tr><td style="text-align:left;">CalculerTotal</td><td style="text-align:left;">montantHeuresNormales, montantHeuresSupp</td><td style="text-align:left;">montantTotal</td></tr></tbody></table></details></details><div class="info custom-block"><p class="custom-block-title"><strong>4) Programmer la solution.</strong></p></div>',60)])])}const f=t(i,[["render",a]]);export{c as __pageData,f as default};
